import{z as s,x as B,o as E,c as A,q as t,j as o,D as e,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"Feldstein–Horioka","description":"","frontmatter":{"title":"Feldstein–Horioka","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/feldstein-horioka.md","filePath":"econ/feldstein-horioka.md","lastUpdated":1791413859000}'),d={name:"econ/feldstein-horioka.md"};function p(C,a,c,h,_,S){const i=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="feldstein–horioka" tabindex="-1">Feldstein–Horioka <a class="header-anchor" href="#feldstein–horioka" aria-label="Permalink to &quot;Feldstein–Horioka&quot;">​</a></h1><div class="epigraph"><p>若资本在国界上可以自由流动，国内储蓄率不必钉住国内投资率；截面上二者几乎一对一，才叫谜。</p><footer>—— Feldstein and Horioka, Domestic Saving and International Capital Flows, Economic Journal 1980</footer></div><p><a href="/econ/saving-investment-id">上一课</a>已经把 \\(S\\equiv I+NX\\) 写成国民账户恒等，并禁止把事后等号读成可贷资金斜率。本课的缺口不是再拆部门，而是：开放之后 \\(S-I\\) 本应被经常账户吸收，为何跨国回归里储蓄率与投资率仍高度相关。Feldstein 与 Horioka（1980）把这条相关叫做对完美资本流动的拒绝。价格指数下一课才给实际变量；本课仍在比率的名义账上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>恒等只说一国之内 \\(S-I=NX\\)，不限制<strong>各国</strong>的 \\(S/Y\\) 与 \\(I/Y\\) 可以差多远。完美资本流动下，投资跟着世界利率与国内边际产出走，储蓄跟着人口与偏好走，二者在截面上不必齐步。Feldstein–Horioka 估的是</p> \\[\\Bigl(\\frac{I}{Y}\\Bigr)_i = \\alpha + \\beta\\Bigl(\\frac{S}{Y}\\Bigr)_i+\\varepsilon_i, \\]<p>OECD 样本里 \\(\\beta\\) 接近 1。缺口是解释这条斜率，而不是把恒等再排一次。\\(\\beta=1\\) 不是会计必然：会计在<strong>每个</strong> \\(i\\) 上都成立，回归问的是跨国变异是否共用。</p><p><span class="marginnote">\\(\\beta\\) 接近 1 被读成「储蓄留在本国」。它也可以是共同冲击：生产率同时抬 \\(S\\) 与 \\(I\\)。相关不是流动成本的充分统计。</span></p><p><span class="marginnote">数字实例：\\(\\beta=0.8\\) 意味着两国储蓄率相差 5 个百分点时，投资率平均仍相差约 4 个百分点，只有 1 个百分点被跨境流动抹平。若资本真的完全流动，这 5 个百分点的差距应几乎全部走经常账户，\\(\\beta\\) 应近 0。1980 年的 OECD 数据给出的却是一个接近 1 的数——谜就在这个反差里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把上一课的 \\(S-I=NX\\) 改写成比率，跨国差分。若世界利率给定、资本完全流动，国内 \\(I/Y\\) 应对齐资本边际产出，与国内 \\(S/Y\\) 脱钩，\\(\\beta\\) 应近 0。观测到的高 \\(\\beta\\) 有三组读法：边境上的摩擦（税、管制、信息）；跨期预算迫使长期 \\(CA\\) 不能乱走，于是长期比率仍相关；内生性——同一冲击进入两边。本课钉住「相关之谜」的陈述，不选唯一因果。</p>',11)),(E(),o(l,null,{default:e(()=>[r(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22S%20%E2%89%A1%20I%2BNX%22%5D%20--%3E%20OPEN%5B%22%E5%BC%80%E6%94%BE%EF%BC%9AS-I%20%E5%8F%AF%E9%9D%9E%E9%9B%B6%22%5D%0A%20%20OPEN%20--%3E%20MOB%5B%22%E5%AE%8C%E7%BE%8E%E6%B5%81%E5%8A%A8%20%E2%87%92%20%CE%B2%20%E5%BA%94%E8%BF%91%200%22%5D%0A%20%20OPEN%20--%3E%20FH%5B%22%E6%88%AA%E9%9D%A2%20%CE%B2%20%E8%BF%91%201%22%5D%0A%20%20FH%20--%3E%20PUZ%5B%22%E6%B5%81%E5%8A%A8%E5%B9%B6%E4%B8%8D%E5%AE%8C%E7%BE%8E%EF%BC%9F%E5%85%B1%E5%90%8C%E5%86%B2%E5%87%BB%EF%BC%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>抛补利率平价是另一套「资本是否可套利」的句子。CIP 与交叉货币基差的实证在<a href="/quant/irp">量化栏</a>，本课不把 \\(\\beta\\) 写成远期基差，也不重写限价簿。</p><h3 id="恒等解释不了斜率" tabindex="-1">恒等解释不了斜率 <a class="header-anchor" href="#恒等解释不了斜率" aria-label="Permalink to &quot;恒等解释不了斜率&quot;">​</a></h3><p>每个国家每一年 \\(S-I=NX\\) 都真。回归用的是各国长期平均的 \\(S/Y\\)、\\(I/Y\\)。大国、封闭、经常账户不能无限逆差，都会把 \\(\\beta\\) 往 1 推——这是规模与跨期约束，不是账户写错。把 FH 当成「储蓄决定投资」的因果，是又一次把恒等读成理论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若资本不能跨境，多出来的储蓄只能变成国内 \\(I\\)，\\(\\beta\\to 1\\)，回到封闭课的事后 \\(S=I\\)。若资本能跨境但居民有本国偏好，或投资带不可贸易的安装成本，相关仍高。Obstfeld 与 Rogoff 后来把运输成本、贸易摩擦放进同一家族：货物都不好跨境，要求权也难完全脱钩。本课不把某一组摩擦升格为唯一微观。</p>',5)),(E(),o(l,null,{default:e(()=>[r(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%9B%BD%E5%86%85%E5%82%A8%E8%93%84%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20CLOSED%5B%22%E4%B8%96%E7%95%8C%E4%B8%80%EF%BC%9A%E8%B5%84%E6%9C%AC%E4%B8%8D%E8%AE%B8%E8%B7%A8%E5%A2%83%22%5D%0A%20%20CLOSED%20--%3E%20ABSORB%5B%22%E5%A4%9A%E5%87%BA%E7%9A%84%E5%82%A8%E8%93%84%E5%8F%AA%E8%83%BD%E4%B9%B0%E5%9B%BD%E5%86%85%E8%B5%84%E6%9C%AC%E5%93%81%22%5D%0A%20%20ABSORB%20--%3E%20BETA1%5B%22I%20%E8%B7%9F%E7%9D%80%20S%20%E8%B5%B0%EF%BC%9Abeta%20%E2%86%92%201%22%5D%0A%20%20SHOCK%20--%3E%20OPEN%5B%22%E4%B8%96%E7%95%8C%E4%BA%8C%EF%BC%9A%E8%B5%84%E6%9C%AC%E8%87%AA%E7%94%B1%E6%B5%81%E5%8A%A8%22%5D%0A%20%20OPEN%20--%3E%20CA%5B%22%E5%8F%98%E6%88%90%E5%AF%B9%E5%A4%96%E5%87%80%E5%80%9F%E5%87%BA%EF%BC%9A%E7%BB%8F%E5%B8%B8%E8%B4%A6%E6%88%B7%E9%A1%BA%E5%B7%AE%22%5D%0A%20%20CA%20--%3E%20BETA0%5B%22I%20%E7%94%B1%E4%B8%96%E7%95%8C%E5%88%A9%E7%8E%87%E5%AE%9A%EF%BC%9Abeta%20%E2%86%92%200%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">直觉类比：把每个国家当成一个家庭。若全村共用一个大钱庄（资本自由流动），谁家多攒的钱可以借给别人盖房，各家「攒钱率」与「盖房率」不必同步。FH 发现各国这两率几乎齐步走，就像发现村民的钱实际上出不了自家大门。</span></p><p>时间维上，一国储蓄率上升可以伴随暂时的 \\(CA\\) 顺差，\\(I\\) 不必同步；截面长期平均抹掉这笔动态，于是谜更像「长期净外资产不能任意漂」，而不是「当年账户不平」。后课经常账户与双赤字会把 \\(S-I\\) 再拆成财政与私人缺口；本课只要求：看到高 \\(\\beta\\) 时先问样本是截面还是短窗。</p><p>金融开放度用法定资本管制、总量 \\(CA\\) 或总量资本流动来量，与 FH 的 \\(\\beta\\) 不必同向：总量可以很大而净额仍小，\\(S\\) 与 \\(I\\) 继续齐步。把「金融全球化」写成 \\(\\beta\\) 必须掉到零，是把总量流动当成净额套利已经完成。上一课的恒等约束的是净额 \\(NX\\)，不是总流入加总流出。</p><p><span class="marginnote">常见误区：看到「资本大进大出」就以为 \\(\\beta\\) 该掉到零。总流入加总流出可以非常大，而净额（\\(S-I\\)）仍很小——跨境热钱来回倒手与一国真实多借多贷是两回事。FH 用的是储蓄、投资这类净额概念，与「总量全球化」的度量不是一把尺，两表打架并不矛盾。</span></p><p><span class="marginnote">大国的 \\(S\\) 冲击会移动世界利率，于是 \\(I\\) 跟着动，\\(\\beta\\) 在大国样本里更高——这是一般均衡，不是「美国尤其封闭」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计新的 \\(\\beta\\)，不把谜写成「全球化失败」的口号。公司金融的优序、FDI 与证券投资的分解，不是这条回归的识别。也不要把 CIP 偏离当 FH 的点估计；市场层平价见 <code>/quant/irp</code>。蒙代尔课用的 \\(i=i^*\\) 是 UIP 退化，与本课的数量相关不是同一句。</p><p>时间序列上 \\(\\beta\\) 可以低于截面：一国暂时用 \\(CA\\) 吸收储蓄冲击，跨年相关弱于各国长期平均。因此「谜已经消失」要声明是哪一种样本。主权风险、原罪会让净外资产不能任意漂，高 \\(\\beta\\) 可以来自跨期预算而不是法定资本管制。把 FH 当开放度指数，会与法定金融开放表打架。</p><p>后课默认：开放会计允许 \\(S\\neq I\\)；经验上长期比率仍高度相关，流动完美不能当默认。下一课把名义账换成实际变量：没有价格指数，\\(I/Y\\) 还只是比率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恒等允许 \\(S-I=NX\\)；FH 问的是跨国 \\(S/Y\\) 与 \\(I/Y\\) 为何齐步。</li><li>完美流动预示 \\(\\beta\\) 近 0；OECD 截面 \\(\\beta\\) 近 1。</li><li>摩擦、跨期约束与共同冲击都是候选，相关不是因果。</li><li>CIP 实证不在本栏，见<a href="/quant/irp">利率平价</a>。</li><li>出处：Feldstein and Horioka, <em>Economic Journal</em> 1980。</li></ul>',11))])}const F=s(d,[["render",p]]);export{m as __pageData,F as default};
